VALUES (12701, 'tt0089913', NULL, 'Revolution', 'Revolution', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/m4LPxSJ8G8KVtySaleJhlTJqKBF.jpg', 'https://image.tmdb.org/t/p/original/qkA2NPLmKLieMIggjC3LtRgEE6S.jpg', 'New York trapper Tom Dobb becomes an unwilling participant in the American Revolution after his son Ned is drafted into the Army by the villainous Sergeant Major Peasy. Tom attempts to find his son, and eventually becomes convinced that he must take a stand and fight for the freedom of the Colonies, alongside the aristocratic rebel Daisy McConnahay. As Tom undergoes his change of heart, the events of the war unfold in large-scale grandeur.', NULL, NULL, 2.0642, 5.4, 0, 10.01, '2026-11-22 21:01:41', '2026-11-22 21:01:41')
