VALUES (39776, 'tt0090952', NULL, 'Peking Opera Blues', '刀馬旦', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/vZvm1TnsXMDcNmN4ByoiNCCYFZt.jpg', 'https://image.tmdb.org/t/p/original/kUUPHesQLQePqobQNjW7UD6WOdA.jpg', 'In 1913 Beijing, three fierce women—disguised rebel Tsao Wan, jewel-seeking Sheung Hung, and opera heiress Pai Niu—embark on a daring quest filled with intrigue and betrayal, challenging societal norms amidst political turmoil and the vibrant world of Peking Opera.', NULL, NULL, 2.849, 7.2, 0, 10.02, '2026-11-22 21:01:41', '2026-11-22 21:01:41')
