VALUES (45935, 'tt0156587', NULL, 'Flowers of Shanghai', '海上花', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/9N3TdNbr5pyT69M5cHODmfc4zTs.jpg', 'https://image.tmdb.org/t/p/original/Anxhh4DeakufTyCdjpuVGF08Gpq.jpg', 'At the end of the 19th century, Shanghai is divided into several foreign concessions. In the British concession, a number of luxurious “flower houses” are reserved for the male elite of the city. Since Chinese dignitaries are not allowed to frequent brothels, these establishments are the only ones that these men can visit. They form a self-contained world, with its own rites, traditions and even its own language. The men don’t only visit the houses to frequent the courtesans but also to dine, smoke opium, play mahjong and relax. The women working there are known as the “flowers of Shanghai”.', NULL, NULL, 1.7809, 6.9, 0, 10.02, '2026-11-22 21:01:41', '2026-11-22 21:01:41')
