VALUES (20713, 'tt0097334', NULL, 'Farewell to the King', 'Farewell to the King', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/TflAOAoV7C0XPqNyIhjhOelr8F.jpg', 'https://image.tmdb.org/t/p/original/wlUlotxtDdh8QpOWdPbleN85HCF.jpg', 'An American soldier who escapes the execution of his comrades by Japanese soldiers in Borneo during WWII becomes the leader of a personal empire among the headhunters in this war story told in the style of Joseph Conrad and Rudyard Kipling. The American is reluctant to rejoin the fight against the Japanese on the urging of a British commando team but conducts a war of vengeance when the Japanese attack his adopted people.', NULL, NULL, 1.4039, 6.019, 0, 10.02, '2026-11-22 21:01:41', '2026-11-22 21:01:41')
