VALUES (102434, 'tt8290362', NULL, 'The Head', 'The Head', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/gFiFKWx8nBjo3iRYcosdJeYUtaX.jpg', 'https://image.tmdb.org/t/p/original/8GAIpNkyVHorYZhCKYT4hC9C7Dv.jpg', 'In an isolated and inaccessible Antarctic research station in which winter has fallen on the South Pole and the sun will soon disappear for the next six months, a small team, known as the Winterers, remain at the Polaris VI Antarctic Research Station to continue their innovative research. Renowned biologist Arthur Wilde is determined to find a solution to climate change, but his quest turns into a nightmare when several of his esteemed scientists suddenly begin to die.', NULL, NULL, 9.1721, 7.057, 0, 8.04, '2026-11-22 21:01:41', '2026-11-22 21:01:41')
