VALUES (1398, 'tt0079944', NULL, 'Stalker', 'Сталкер', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/1qhOyf5C4s9ZdvY8d5JDx9DFMeT.jpg', 'https://image.tmdb.org/t/p/original/6yrbWzzrPp7pwz6zHdifspJk8t3.jpg', 'Near a gray and unnamed city is the Zone, a place guarded by barbed wire and soldiers, and where the normal laws of physics are victim to frequent anomalies. A stalker guides two men into the Zone, specifically to an area in which deep-seated desires are granted.', NULL, NULL, 6.8196, 8.07, 0, 1.72198928571428552e+02, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
