VALUES (8966, 'tt1099212', NULL, 'Twilight', 'Twilight', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', 'https://image.tmdb.org/t/p/original/weAYfu6FfrNxEDJ3xH1XpgQcqUv.jpg', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t stay away from him, a fatal move that endangers her own life.', NULL, NULL, 42.6628, 6.273, 0, 129.26552, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
