VALUES (1920, 'tt0098936', NULL, 'Twin Peaks', 'Twin Peaks', 'tv', 1990, 'https://image.tmdb.org/t/p/w500/lA9CNSdo50iQPZ8A2fyVpMvJZAf.jpg', 'https://image.tmdb.org/t/p/original/dZklTql88IDOmkC3JAYQSTgyK6f.jpg', 'The body of Laura Palmer is washed up on a beach near the small Washington state town of Twin Peaks. FBI Special Agent Dale Cooper is called in to investigate her strange demise only to uncover a web of mystery that ultimately leads him deep into the heart of the surrounding woodland and his very own soul.', NULL, NULL, 65.4345, 8.339, 0, 2.97414266211604058e+02, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
