VALUES (10054, 'tt0227538', NULL, 'Spy Kids', 'Spy Kids', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/j3rUkHIAAoKr6jU30q3Db4fcIF9.jpg', 'https://image.tmdb.org/t/p/original/aFHAnOI1sjHktgEX5lykeSiUZ1C.jpg', 'Carmen and Juni think their parents are boring. Little do they know that in their day, Gregorio and Ingrid Cortez were the top secret agents from their respective countries. They gave up that life to raise their children. Now, the disappearances of several of their old colleagues forces the Cortez'' return from retirement. What they didn''t count on was Carmen and Juni joining the "family business."', NULL, NULL, 6.1878, 5.825, 0, 5.67296296296296347e+01, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
