VALUES (10307, 'tt0145531', NULL, 'Stigmata', 'Stigmata', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/sKS1Vuqj7OQpOumfs6ArC0TICTN.jpg', 'https://image.tmdb.org/t/p/original/i9tMK3nzmZJ8MBG92iIxGXHWDq4.jpg', 'A young woman with no strong religious beliefs, Frankie Paige begins having strange and violent experiences, showing signs of the wounds that Jesus received when crucified. When the Vatican gets word of Frankie''s situation, a high-ranking cardinal requests that the Rev. Andrew Kiernan investigate her case. Soon Kiernan realizes that very sinister forces are at work, and tries to rescue Frankie from the entity that is plaguing her.', NULL, NULL, 3.5386, 6.3, 0, 2.03152941176470562e+01, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
