VALUES (1100988, 'tt10548174', NULL, '28 Years Later', '28 Years Later', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/n5FygjEppOvac6yEaowi26nTyw3.jpg', 'https://image.tmdb.org/t/p/original/6WqqEjiycNvDLjbEClM1zCwIbDD.jpg', 'Twenty-eight years after the Rage virus outbreak, a heavily-defended island survives connected to the mainland by a single causeway. When one of the group leaves the island into the dark heart of the mainland, he discovers secrets, wonders, and horrors that have mutated not only the infected but other survivors as well.', NULL, NULL, 16.4717, 6.594, 0, 3.33880645161290345e+01, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
