VALUES (421, 'tt0362270', NULL, 'The Life Aquatic with Steve Zissou', 'The Life Aquatic with Steve Zissou', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/qZoFLNBC78jzboWeDH6Ha0qavF2.jpg', 'https://image.tmdb.org/t/p/original/7tWktnLQ81G8pHUkhuTebcTkcB3.jpg', 'Renowned oceanographer Steve Zissou has sworn vengeance upon the rare shark that devoured a member of his crew. In addition to his regular team, he is joined on his boat by Ned, a man who believes Zissou to be his father, and Jane, a journalist pregnant by a married man. They travel the sea, all too often running into pirates and, perhaps more traumatically, various figures from Zissou''s past, including his estranged wife, Eleanor.', NULL, NULL, 4.197, 7.069, 0, 2.22311764705882346e+01, '2026-07-15 12:01:52', '2026-11-22 21:01:41')
