VALUES (1465063, 'tt36583977', NULL, 'Forgotten Island', 'Forgotten Island', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', 'https://image.tmdb.org/t/p/original/2o9FzuBzCqrDTdlHRuEVnGD2d5h.jpg', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', NULL, NULL, 64.7617, 8.037, 0, 7.18, '2026-08-03 14:31:56', '2026-11-22 21:01:41')
