VALUES (17496, 'tt0081696', NULL, 'Urban Cowboy', 'Urban Cowboy', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/2uKWi1Hb6yqkmOixRgKVwrzxljA.jpg', 'https://image.tmdb.org/t/p/original/ySh8pIJ7iWdbtDLmhFbX28TQnU9.jpg', 'After moving to Pasadena, Texas, country boy Bud Davis starts hanging around a bar called Gilley''s, where he falls in love with Sissy, a cowgirl who believes the sexes are equal. They eventually marry, but their relationship is turbulent due to Bud''s traditional view of gender roles. Jealousy over his rival leads to their separation, but Bud attempts to win Sissy back by triumphing at Gilley''s mechanical bull-riding competition.', NULL, NULL, 2.2461, 6.5, 0, 1.1975999999999999e+01, '2026-08-04 03:20:13', '2026-11-22 21:01:41')
