VALUES (625, 'tt0087553', NULL, 'The Killing Fields', 'The Killing Fields', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/cX6Bv7natnZwQjsV9bLL8mmWjkS.jpg', 'https://image.tmdb.org/t/p/original/c7OeJd34rc9bI1DXqd4ucb1wVrf.jpg', 'New York Times reporter Sydney Schanberg is on assignment covering the Cambodian Civil War, with the help of local interpreter Dith Pran and American photojournalist Al Rockoff. When the U.S. Army pulls out amid escalating violence, Schanberg makes exit arrangements for Pran and his family. Pran, however, tells Schanberg he intends to stay in Cambodia to help cover the unfolding story — a decision he may regret as the Khmer Rouge rebels move in.', NULL, NULL, 4.326, 7.5, 0, 6.21, '2026-08-05 03:13:48', '2026-11-22 21:01:41')
