VALUES (746, 'tt0093389', NULL, 'The Last Emperor', 'The Last Emperor', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/7TILJhdeJAaEyDiwvJZMo9SQBoe.jpg', 'https://image.tmdb.org/t/p/original/k29qVmwWwR0i5A1UMIws1Vmv6hV.jpg', 'A dramatic history of Pu Yi, the last of the Emperors of China, from his lofty birth and brief reign in the Forbidden City, the object of worship by half a billion people; through his abdication, his decline and dissolute lifestyle; his exploitation by the invading Japanese, and finally to his obscure existence as just another peasant worker in the People''s Republic.', NULL, NULL, 5.5057, 7.59, 0, 8.918, '2026-08-10 02:34:01', '2026-11-22 21:01:41')
