VALUES (39962, 'tt0374262', NULL, 'Tamala 2010: A Punk Cat in Space', 'TAMALA2010 a punk cat in space', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/q4zfQs8eA3QaW2xdXqv8c5usxCt.jpg', 'https://image.tmdb.org/t/p/original/mCcG1ZVH9DnHRC5cwhrCbUiNQp3.jpg', 'Tamala is a cat living on Planet Cat Earth in the Feline Galaxy. In attempt to leave the Feline Galaxy, which is practically owned by a mega corporation called Catty & Co., she crashes on the violence-ridden Planet Q where she meets Michelangelo. Together they have fun, while Tamala seaches for her connections to Catty & Co. and her mysterious homeworld Orion.', NULL, NULL, 1.1904, 6.3, 0, 6.0166666666666666e+00, '2026-08-11 02:46:38', '2026-11-22 21:01:41')
