VALUES (11224, 'tt0042332', NULL, 'Cinderella', 'Cinderella', 'movie', 1950, 'https://image.tmdb.org/t/p/w500/4nssBcQUBadCTBjrAkX46mVEKts.jpg', 'https://image.tmdb.org/t/p/original/puJKgNcWaGgMk5VHanSSomUTpmw.jpg', 'Cinderella has faith her dreams of a better life will come true. With help from her loyal mice friends and a wave of her Fairy Godmother''s wand, Cinderella''s rags are magically turned into a glorious gown and off she goes to the Royal Ball. But when the clock strikes midnight, the spell is broken, leaving a single glass slipper... the only key to the ultimate fairy-tale ending!', NULL, NULL, 13.2508, 7.056, 0, 11.51, '2026-08-11 02:46:38', '2026-11-22 21:01:41')
