VALUES (11287, 'tt0104694', NULL, 'A League of Their Own', 'A League of Their Own', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/f9BtX6wYOwJUyfUr4vyeT3COz6m.jpg', 'https://image.tmdb.org/t/p/original/kb2FuXGruaPA6ErjOpcifpCyPyY.jpg', 'As America''s stock of athletic young men is depleted during World War II, a professional all-female baseball league springs up in the Midwest, funded by publicity-hungry candy maker Walter Harvey. Competitive sisters Dottie Hinson and Kit Keller spar with each other, scout Ernie Capadino and grumpy has-been coach Jimmy Dugan on their way to fame.', NULL, NULL, 7.3989, 7.207, 0, 4.0275, '2026-08-11 22:09:33', '2026-11-22 21:01:41')
