VALUES (2723, 'tt0278238', NULL, 'Samurai Jack', 'Samurai Jack', 'tv', 2001, 'https://image.tmdb.org/t/p/w500/ddZ7Q2WZ0xAHkVXYvcEgNGFgVkw.jpg', 'https://image.tmdb.org/t/p/original/CrVAqxtdmvelqVcj8pVeQg7wNV.jpg', 'A great warrior is displaced to the distant future by the evil shape-shifting wizard Aku. The world has become a bleak place under the rule of Aku, segregated into fantastic tribes and ruled by Aku''s evil robot warlords. Jack travels this foreign landscape in search of a time portal that can return him to his home time so he can "undo the future that is Aku!".', NULL, NULL, 29.7371, 8.417, 0, 10.76, '2026-08-11 22:09:33', '2026-11-22 21:01:41')
