VALUES (419546, 'tt6156350', NULL, 'HyperNormalisation', 'HyperNormalisation', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/tTqI2xoB7cGO7HASB22Sss6x44J.jpg', 'https://image.tmdb.org/t/p/original/54HEQPoD7zWGGaCusDnDBG3aCFO.jpg', 'We live in a world where the powerful deceive us. We know they lie. They know we know they lie. They do not care. We say we care, but we do nothing, and nothing ever changes. It is normal. Welcome to the post-truth world. How we got to where we are now…', NULL, NULL, 1.5245, 7.474, 0, 2.03, '2026-08-12 02:31:31', '2026-11-22 21:01:41')
