VALUES (783, 'tt0083987', NULL, 'Gandhi', 'Gandhi', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/rOXftt7SluxskrFrvU7qFJa5zeN.jpg', 'https://image.tmdb.org/t/p/original/gum3tuO1zKHBdElSQPS08PJ1w67.jpg', 'In the early years of the 20th century, Mohandas K. Gandhi, a British-trained lawyer, forsakes all worldly possessions to take up the cause of Indian independence. Faced with armed resistance from the British government, Gandhi adopts a policy of ''passive resistance'', endeavouring to win freedom for his people without resorting to bloodshed.', NULL, NULL, 5.3043, 7.551, 0, 9.51333333333333364e+00, '2026-08-12 02:31:31', '2026-11-22 21:01:41')
