VALUES (276908, 'tt2965412', NULL, 'Comet', 'Comet', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/4zOOSa5zyJDvqDDKFwUQVMK6eDe.jpg', 'https://image.tmdb.org/t/p/original/znDbUAz0uPgc329iHBiobnnYA2P.jpg', 'When a chance encounter brings together the cynical Dell and the quick-witted Kimberly, the stage is set for a tempestuous love affair that unfolds like a puzzle. As the film zigzags back and forth in time — from a meteor shower in LA, to an encounter in a Paris hotel room, to a fateful phone call — an unforgettable portrait of a relationship emerges.', NULL, NULL, 1.2545, 6.6, 0, 9.91400000000000147e+00, '2026-08-20 01:43:50', '2026-11-22 21:01:41')
