VALUES (314, 'tt0327554', NULL, 'Catwoman', 'Catwoman', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/pvnPgukFyEKgCzyOxyLiwyZ8T1C.jpg', 'https://image.tmdb.org/t/p/original/cxAr9Su5gYfx16vxtS2Zi6qc5DZ.jpg', 'Liquidated after discovering a corporate conspiracy, mild-mannered graphic artist Patience Phillips washes up on an island, where she''s resurrected and endowed with the prowess of a cat — and she''s eager to use her new skills... as a vigilante. Before you can say "cat and mouse", handsome gumshoe Tom Lone is on her tail, fascinated by both of her personas.', NULL, NULL, 6.468, 4.634, 0, 5.32666666666666621e+00, '2026-08-20 01:43:50', '2026-11-22 21:01:41')
